CREATE TABLE IF NOT EXISTS quant_model_versions(id bigserial PRIMARY KEY,model_version text UNIQUE,model_type text,feature_version text,trained_from timestamptz,trained_to timestamptz,train_samples integer,validation_samples integer,holdout_tested boolean NOT NULL DEFAULT false,parameters jsonb NOT NULL DEFAULT '{}'::jsonb,metrics jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'SHADOW',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quant_decisions(id bigserial PRIMARY KEY,quant_decision_id text UNIQUE,session_id text,market_event_id text,ground_truth_id text,decision_timestamp timestamptz,feature_version text,model_version text,calibration_version text,policy_version text,direction text,p_up numeric,p_down numeric,p_no_edge numeric,calibrated_confidence numeric,regime text,neighbor_count integer,neighbor_p_up numeric,neighbor_p_down numeric,feature_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,components jsonb NOT NULL DEFAULT '{}'::jsonb,shadow_only boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS quant_decisions_session_idx ON quant_decisions(session_id,created_at DESC);
